def components(grid):
 h,w=len(grid),len(grid[0]); seen=set(); comps=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c] and (r,c) not in seen:
    stack=[(r,c)];seen.add((r,c));pts=[]
    while stack:
     x,y=stack.pop();pts.append((x,y))
     for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
      q=(x+dx,y+dy)
      if 0<=q[0]<h and 0<=q[1]<w and grid[q[0]][q[1]] and q not in seen:
       seen.add(q);stack.append(q)
    r0=min(x for x,y in pts);r1=max(x for x,y in pts);c0=min(y for x,y in pts);c1=max(y for x,y in pts)
    arr=[row[c0:c1+1] for row in grid[r0:r1+1]]
    comps.append((r0,c0,arr))
 return sorted(comps,key=lambda x:(x[1],x[0]))
